def gen(rng):
    OPEN = '([{'
    CLOSE = ')]}'
    ALPHA = 'abcdefghijklmnopqrstuvwxyz0123456789'

    def build(target, popen, pclose):
        out = []
        st = []
        flag = []
        while len(out) + 2 * len(st) + 3 <= target:
            r = rng.random()
            if r < popen:
                if st:
                    flag[-1] = True
                k = rng.randrange(3)
                out.append(OPEN[k])
                st.append(k)
                flag.append(False)
            elif st and flag[-1] and r < popen + pclose:
                out.append(CLOSE[st.pop()])
                flag.pop()
                if flag:
                    flag[-1] = True
            else:
                out.append(rng.choice(ALPHA))
                if st:
                    flag[-1] = True
        while st:
            if not flag[-1]:
                out.append(rng.choice(ALPHA))
            out.append(CLOSE[st.pop()])
            flag.pop()
            if flag:
                flag[-1] = True
        return ''.join(out)

    def pad(s, n):
        return s + 'z' * (n - len(s))

    tests = ['a', 'abc', '(a)', '[a]b{c}', 'x(y[z])', '{a}{b}{c}', 'a(b)c(b)d', '((a))', 'a[b{c(d)e}f]g']
    for _ in range(14):
        tests.append(build(rng.randint(3, 60), rng.choice([0.2, 0.35, 0.5]), rng.choice([0.15, 0.3])))
    for _ in range(6):
        tests.append(build(rng.randint(100, 300), rng.choice([0.25, 0.4]), 0.25))
    tests.append(build(1500, 0.3, 0.25))
    k = 49999
    deep = '(' * k + 'ab' + ')' * k
    tests.append(deep)
    tests.append(''.join('[' + 'x' + ']' for _ in range(33333)) + 'y')
    tests.append(pad(build(100000, 0.45, 0.2), 100000))
    tests.append(pad(build(100000, 0.3, 0.3), 100000))
    return tests

